"    private static final int WRAP_WIDTH = 400;

    public void renderWrappedText(Graphics2D g2d, String text, int x, int y) {
        FontRenderContext frc = g2d.getFontRenderContext();
        TextLayout textLayout = new TextLayout(text, g2d.getFont(), frc);
        float wrappingWidth = WRAP_WIDTH;
        float penX = x;
        float penY = y + textLayout.getAscent();
        for (String line : getWrappedLines(text, g2d)) {
            textLayout = new TextLayout(line, g2d.getFont(), frc);
            textLayout.draw(g2d, penX, penY);
            penY += textLayout.getAscent() + textLayout.getDescent() + textLayout.getLeading();
        }
    }

    private String[] getWrappedLines(String text, Graphics2D g2d) {
        if (g2d.getFontMetrics().stringWidth(text) < WRAP_WIDTH) {
            return new String[] {text};
        }
        String[] words = text.split("\\s");
        StringBuilder wrappedText = new StringBuilder();
        int lineLength = 0;
        for (String word : words) {
            if (g2d.getFontMetrics().stringWidth(word) + lineLength < WRAP_WIDTH) {
                wrappedText.append(word).append(" ");
                lineLength += g2d.getFontMetrics().stringWidth(word + " ");
            } else {
                wrappedText.append("\n").append(word).append(" ");
                lineLength = g2d.getFontMetrics().stringWidth(word + " ");
            }
        }
        return wrappedText.toString().split("\n");
    }"
